root=Path('/tmp/b4-ci-swift-evidence/native/DerivedData/Build/Products')
for app in sorted(root.glob('*/*.app')):
 plist=app/'Contents/Info.plist' if (app/'Contents/Info.plist').exists() else app/'Info.plist'
 if not plist.exists():continue
 info=plistlib.loads(plist.read_bytes());exe=app/('Contents/MacOS' if (app/'Contents').exists() else '')/info['CFBundleExecutable']
 product=next(p for p in native['products'] if p['configuration']==app.parent.name and p['bundle_id']==info['CFBundleIdentifier'])
 assert hashlib.sha256(exe.read_bytes()).hexdigest()==product['binary_sha256'];assert hashlib.sha256(plist.read_bytes()).hexdigest()==product['info_plist_sha256']
 origin='fresh macOS build'
 if product['platforms']==['iPhoneSimulator']:
  previous=next(p for p in reuse['products'] if p['configuration']==product['configuration'] and p['bundle_id']==product['bundle_id'])
  assert product['binary_sha256']==previous['binary_sha256'] and product['info_plist_sha256']==previous['info_plist_sha256'];origin='reused prior iOS build, unchanged relevant graph/inputs'
 locations.append(dict(path=str(app),executable=str(exe),configuration=product['configuration'],bundle_id=product['bundle_id'],binary_sha256=product['binary_sha256'],plist_sha256=product['info_plist_sha256'],origin=origin,signing_allowed=False))
assert len(locations)==6 and sum(p['origin'].startswith('reused') for p in locations)==3
reuse['actual_binary_and_plist_digests_reverified']=True;reuse['reverified_at']=datetime.datetime.now(datetime.timezone.utc).isoformat();(out/'ios-reuse.json').write_text(json.dumps(reuse,indent=2)+'\n');(out/'artifact-locations.json').write_text(json.dumps(locations,indent=2)+'\n')
